import{_ as a,o as n,c as l,a0 as e}from"./chunks/framework.DqMqoJl9.js";const q=JSON.parse('{"title":"Array.prototype.splice()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Array/splice.md","filePath":"jsApi/Array/splice.md","lastUpdated":1791038339000}'),p={name:"jsApi/Array/splice.md"};function o(t,s,r,c,i,u){return n(),l("div",null,[...s[0]||(s[0]=[e(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Array/splice" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/splice" target="_blank">en</a></p><h1 id="array-prototype-splice" tabindex="-1">Array.prototype.splice() <a class="header-anchor" href="#array-prototype-splice" aria-label="Permalink to &quot;Array.prototype.splice()&quot;">​</a></h1><p>splice() 方法通过删除现有元素和/或添加新元素来更改数组的内容。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> myFish </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [</span><span style="color:#032F62;">&quot;angel&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;clown&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;mandarin&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;sturgeon&quot;</span><span style="color:#24292E;">];</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;drum&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// myFish is [&quot;angel&quot;, &quot;clown&quot;, &quot;drum&quot;, &quot;mandarin&quot;, &quot;sturgeon&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// myFish is [&quot;angel&quot;, &quot;clown&quot;, &quot;mandarin&quot;, &quot;sturgeon&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;splice&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;parrot&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// myFish is [&quot;angel&quot;, &quot;clown&quot;, &quot;splice&quot;, &quot;parrot&quot;, &quot;sturgeon&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br></div></div><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">array.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(start)</span></span>
<span class="line"><span style="color:#24292E;">array.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(start, deleteCount)</span></span>
<span class="line"><span style="color:#24292E;">array.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(start, deleteCount, item1, item2, </span><span style="color:#D73A49;">...</span><span style="color:#24292E;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>start​</code> 指定修改的开始位置（从0计数）。如果超出了数组的长度，则从数组末尾开始添加内容；如果是负值，则表示从数组末位开 始的第几位（从1计数）。</li><li><code>deleteCount 可选</code> 整数，表示要移除的数组元素的个数。如果 deleteCount 是 0，则不移除元素。这种情况下，至少应添加一个新 元素。如果 deleteCount 大于start 之后的元素的总数，则从 start 后面的元素都将被删除（含第 start 位）。如果deleteCount被省 略，则其相当于(arr.length - start)。</li><li><code>item1, item2, ... 可选</code> 要添加进数组的元素,从start 位置开始。如果不指定，则 splice() 将只删除数组元素。</li></ul><h3 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h3><p>由被删除的元素组成的一个数组。如果只删除了一个元素，则返回只包含一个元素的数组。如果没有删除元素，则返回空数组。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>如果添加进数组的元素个数不等于被删除的元素个数，数组的长度会发生相应的改变。</p><h2 id="提示和注释" tabindex="-1">提示和注释 <a class="header-anchor" href="#提示和注释" aria-label="Permalink to &quot;提示和注释&quot;">​</a></h2><p>注释：请注意，splice() 方法与 slice() 方法的作用是不同的，splice() 方法会直接对数组进行修改。</p><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><p>使用 splice()</p><p>如下代码演示了 splice 的用法：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> myFish </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> [</span><span style="color:#032F62;">&quot;angel&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;clown&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;mandarin&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;surgeon&quot;</span><span style="color:#24292E;">];</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//从第 2 位开始删除 0 个元素，插入 &quot;drum&quot;</span></span>
<span class="line"><span style="color:#D73A49;">var</span><span style="color:#24292E;"> removed </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;drum&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">//运算后的 myFish:[&quot;angel&quot;, &quot;clown&quot;, &quot;drum&quot;, &quot;mandarin&quot;, &quot;surgeon&quot;]</span></span>
<span class="line"><span style="color:#6A737D;">//被删除元素数组：[]，没有元素被删除</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//从第 3 位开始删除 1 个元素</span></span>
<span class="line"><span style="color:#24292E;">removed </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">//运算后的myFish：[&quot;angel&quot;, &quot;clown&quot;, &quot;drum&quot;, &quot;surgeon&quot;]</span></span>
<span class="line"><span style="color:#6A737D;">//被删除元素数组：[&quot;mandarin&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//从第 2 位开始删除 1 个元素，然后插入 &quot;trumpet&quot;</span></span>
<span class="line"><span style="color:#24292E;">removed </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">1</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;trumpet&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">//运算后的myFish: [&quot;angel&quot;, &quot;clown&quot;, &quot;trumpet&quot;, &quot;surgeon&quot;]</span></span>
<span class="line"><span style="color:#6A737D;">//被删除元素数组：[&quot;drum&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//从第 0 位开始删除 2 个元素，然后插入 &quot;parrot&quot;, &quot;anemone&quot; 和 &quot;blue&quot;</span></span>
<span class="line"><span style="color:#24292E;">removed </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">0</span><span style="color:#24292E;">, </span><span style="color:#005CC5;">2</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;parrot&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;anemone&quot;</span><span style="color:#24292E;">, </span><span style="color:#032F62;">&quot;blue&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">//运算后的myFish：[&quot;parrot&quot;, &quot;anemone&quot;, &quot;blue&quot;, &quot;trumpet&quot;, &quot;surgeon&quot;]</span></span>
<span class="line"><span style="color:#6A737D;">//被删除元素的数组：[&quot;angel&quot;, &quot;clown&quot;]</span></span>
<span class="line"></span>
<span class="line"><span style="color:#6A737D;">//从第 3 位开始删除 2 个元素</span></span>
<span class="line"><span style="color:#24292E;">removed </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> myFish.</span><span style="color:#6F42C1;">splice</span><span style="color:#24292E;">(</span><span style="color:#005CC5;">3</span><span style="color:#24292E;">, Number.MAX_VALUE);</span></span>
<span class="line"><span style="color:#6A737D;">//运算后的myFish: [&quot;parrot&quot;, &quot;anemone&quot;, &quot;blue&quot;]</span></span>
<span class="line"><span style="color:#6A737D;">//被删除元素的数组：[&quot;trumpet&quot;, &quot;surgeon&quot;]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br></div></div><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 3st Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table>`,20)])])}const d=a